\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Dark Theme Colors ──
\definecolor{primary}{HTML}{0EA5E9}     % electric blue
\definecolor{secondary}{HTML}{14B8A6}   % teal
\definecolor{accent}{HTML}{F59E0B}      % warm gold
\definecolor{bgposter}{HTML}{0F172A}    % deep navy / charcoal
\definecolor{cardbg}{HTML}{1E293B}      % lighter charcoal for cards
\definecolor{cardtitlebg}{HTML}{0F172A}
\definecolor{textdark}{HTML}{F8FAFC}    % light text for dark background
\definecolor{textgray}{HTML}{94A3B8}    % gray text
\definecolor{stathighlight}{HTML}{1E293B}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=40pt, itemsep=16pt, parsep=6pt, topsep=12pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=40pt, itemsep=16pt, parsep=6pt, topsep=12pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{26}{32}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles ──
\tcbset{
  basecard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=cardbg,
    left=32pt, right=32pt, top=24pt, bottom=24pt,
    toptitle=16pt, bottomtitle=16pt,
    valign=top, drop shadow={opacity=0.6, color=black},
    coltext=textdark,
  },
  bluecard/.style={
    basecard,
    borderline west={10pt}{0pt}{primary},
    fonttitle=\fontsize{44}{52}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=cardtitlebg,
    titlerule=3pt, titlerule style={primary!50},
  },
  tealcard/.style={
    basecard,
    borderline west={10pt}{0pt}{secondary},
    fonttitle=\fontsize{44}{52}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=cardtitlebg,
    titlerule=3pt, titlerule style={secondary!50},
  },
  goldcard/.style={
    basecard,
    borderline west={10pt}{0pt}{accent},
    fonttitle=\fontsize{44}{52}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardtitlebg,
    titlerule=3pt, titlerule style={accent!50},
  },
  highlightcard/.style={
    basecard,
    colback=primary!20!cardtitlebg,
    borderline west={10pt}{0pt}{primary},
    fonttitle=\fontsize{44}{52}\selectfont\bfseries\color{textdark},
    coltitle=textdark, colbacktitle=primary,
  },
}

