\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=16mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=cardbg, colframe=cardbg, colupper=textdark,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=32pt, bottom=32pt,
  halign=center, valign=center,
  drop shadow={opacity=0.6, color=black}
]{name=title, column=1, span=3, between=top and row3}{
  {\fontsize{100}{120}\selectfont\bfseries Mapping Neural Circuit Architecture}\\[20pt]
  {\fontsize{64}{76}\selectfont\bfseries\color{primary} Advances in Brain Connectivity Analysis}\\[32pt]
  {\fontsize{48}{56}\selectfont \textit{Nature} (2024) | DOI: 10.1038/s41586-024-07487-w}\\[20pt]
  {\fontsize{40}{48}\selectfont\color{textgray} A landmark study revealing principles of neural circuit organization through large-scale connectomics}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=cardtitlebg, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=0pt, bottom=0pt,
  valign=center, borderline south={6pt}{0pt}{primary!40},
]{name=stats, column=1, span=3, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.24\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.9\linewidth}{%
      \centering\vspace{24pt}%
      {\fontsize{90}{108}\selectfont\bfseries\color{primary} \char`\~125k}\\[12pt]
      {\fontsize{38}{46}\selectfont\color{textdark} Neurons Mapped}\vspace{24pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    \fcolorbox{secondary!40}{stathighlight}{\parbox{0.9\linewidth}{%
      \centering\vspace{24pt}%
      {\fontsize{90}{108}\selectfont\bfseries\color{secondary} \char`\~54M}\\[12pt]
      {\fontsize{38}{46}\selectfont\color{textdark} Synapses Catalogued}\vspace{24pt}%
    }}
  \end{minipage}\hfill
