      \centering\vspace{24pt}%
      {\fontsize{90}{108}\selectfont\bfseries\color{accent} 37}\\[12pt]
      {\fontsize{38}{46}\selectfont\color{textdark} Circuit Motifs}\vspace{24pt}%
    }}
