  \begin{minipage}[c]{0.24\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.9\linewidth}{%
      \centering\vspace{24pt}%
      {\fontsize{90}{108}\selectfont\bfseries\color{primary} 94.2\%}\\[12pt]
      {\fontsize{38}{46}\selectfont\color{textdark} Accuracy}\vspace{24pt}%
    }}
  \end{minipage}
}

% ══ COLUMN 1 ══
\posterbox[bluecard, title={Background \& Motivation}
]{name=bg, column=1, between=row5 and row10}{
  \fontsize{38}{48}\selectfont
  \begin{itemize}
    \item \textbf{The Gap:}\\ Classical neuroanatomy lacks the resolution and scale for complete circuit-level wiring diagrams.
    \item \textbf{The Advance:}\\ Convergence of electron microscopy, automated segmentation, and machine learning enables large-scale connectomics.
    \item \textbf{The Goal:}\\ Bridge structural connectivity and functional organization to decode brain information processing.
  \end{itemize}
}

\posterbox[tealcard, title={Methodology \& Pipeline}
]{name=method, column=1, between=row10 and row20}{
  \fontsize{38}{48}\selectfont
  Multi-modal pipeline combining serial-section electron microscopy (EM) with automated neuron reconstruction.

  \vspace{32pt}
  \colorbox{primary!20!cardbg}{\parbox{0.94\linewidth}{
    \vspace{8pt}
    \textbf{1. Imaging:} Serial-section EM\\
    Resolution: $4\text{ nm} \times 4\text{ nm} \times 30\text{ nm}$
    \vspace{8pt}
  }}
  \vspace{24pt}

  \colorbox{secondary!20!cardbg}{\parbox{0.94\linewidth}{
    \vspace{8pt}
    \textbf{2. Segmentation:}\\
    Deep learning automated tracing\\
    + human proofreading
    \vspace{8pt}
  }}
  \vspace{24pt}

  \colorbox{accent!20!cardbg}{\parbox{0.94\linewidth}{
    \vspace{8pt}
    \textbf{3. Synapse Detection:}\\
    CNN classifier\\
    Achieving \textbf{94.2\% accuracy}
    \vspace{8pt}
  }}
  \vspace{24pt}

  \colorbox{primary!20!cardbg}{\parbox{0.94\linewidth}{
    \vspace{8pt}
    \textbf{4. Circuit Analysis:}\\
    Graph-theoretic motif detection\\
    \& clustering algorithms
    \vspace{8pt}
  }}
}

% ══ COLUMN 2 ══
\posterbox[goldcard, title={Key Findings: Circuit Architecture}
]{name=findings, column=2, between=row5 and row20}{
  \fontsize{38}{48}\selectfont
  Connectomic analysis revealed fundamental principles of neural circuit organization:

  \vspace{32pt}
  \begin{itemize}
    \item \textbf{Modular Wiring Logic:}\\
      Discovered \textbf{37 distinct connectivity motifs} acting as recurring building blocks of larger circuits.
      \vspace{20pt}
    \item \textbf{Hub Neurons Drive Network:}\\
      A rare population (\textbf{\char`\~3.5\%}) of hub neurons accounts for over \textbf{28\% of total synaptic output}.
      \vspace{20pt}
    \item \textbf{Layer-Specific Connectivity:}\\
      Recurrent connections are enriched in Layer 5.\\
      Ratio of \textbf{4.7 : 1} (recurrent vs. feedforward).
      \vspace{20pt}
    \item \textbf{Cell-Type-Specific Wiring:}\\
      Inhibitory interneurons form connections with \textbf{6.2$\times$ higher specificity} than excitatory neurons.
  \end{itemize}

  \vspace{64pt}
  \centering
  \renewcommand{\arraystretch}{1.8}
  \begin{tabular}{p{0.50\linewidth} p{0.45\linewidth}}
    \rowcolor{primary!30!cardbg}
    \textbf{Metric} & \textbf{Quantitative Result} \\
    \rowcolor{cardtitlebg}
    Total Neurons & \char`\~125,000 \\
    \rowcolor{cardbg}
    Total Synapses & \char`\~54 million \\
    \rowcolor{cardtitlebg}
    Connectivity Motifs & 37 distinct types \\
    \rowcolor{cardbg}
    L5 Recurrent Ratio & 4.7 : 1 \\
    \rowcolor{cardtitlebg}
    Inhibitory Specificity & 6.2$\times$ higher \\
  \end{tabular}
}

% ══ COLUMN 3 ══
\posterbox[highlightcard, title={Implications \& Impact}
]{name=impact, column=3, between=row5 and row13}{
  \fontsize{38}{48}\selectfont
  \begin{itemize}
    \item \textbf{Finite Vocabulary of Circuits:}\\
      Modular motifs suggest the brain employs logic-gate-like elements for computation.
      \vspace{16pt}
    \item \textbf{Vulnerability \& Targetability:}\\
      Hub neurons explain how focal lesions or targeted stimulation (e.g., BCI) produce widespread network effects.
      \vspace{16pt}
    \item \textbf{Challenging Assumptions:}\\
      High specificity of inhibitory neurons rewrites the ``broad inhibitory blanket'' theory of cortical regulation.
  \end{itemize}
}

\posterbox[bluecard, title={Future Directions}
]{name=future, column=3, between=row13 and row18}{
  \fontsize{38}{48}\selectfont
  \begin{itemize}
    \item \textbf{Cross-Region Connectomics:}\\
      Extend mapping to subcortical regions and whole-brain volumes.
      \vspace{16pt}
    \item \textbf{Cross-Species Scaling:}\\
      Comparative connectomics to identify evolutionarily conserved motifs.
      \vspace{16pt}
    \item \textbf{Open Science:}\\
      Dataset and CNN analysis tools released to accelerate community discovery.
  \end{itemize}
}

\posterbox[tealcard, title={Acknowledgements}
]{name=ack, column=3, between=row18 and row20}{
  \fontsize{32}{40}\selectfont
  Data source: \textit{Nature} (2024), DOI: 10.1038/s41586-024-07487-w.
  \vspace{16pt}\\
  This poster was generated to summarize the landmark study on large-scale connectomics for the neuroscience community.
}

\end{tcbposter}
\end{document}

